public class GoodCode {
    public static class OrderParams {
        public int a;
        public int b;
        public int c;
        public int d;
        public int e;
        public int f;
    }

    public int processOrder(OrderParams params) {
        int result = 0;
        if (params.a > 10) result += params.a;
        if (params.b > 10) result += params.b;
        if (params.c > 10) result += params.c;
        if (params.d > 10) result += params.d;
        if (params.e > 10) result += params.e;
        if (params.f > 10) result += params.f;
        return result;
    }
}

public class GoodCode {
    public int processOrder(int a, int b, int c, int d, int e, int f) {
        return sumIfGreaterThanTen(a, b, c, d, e, f);
    }

    private int sumIfGreaterThanTen(int... numbers) {
        int sum = 0;
        for (int number : numbers) {
            if (number > 10) {
                sum += number;
            }
        }
        return sum;
    }
}

