        int result = 0;
        if (a > 10) {
            result += a;
            if (b > 10) {
                result += b;
                if (c > 10) {
                    result += c;
                    if (d > 10) {
                        result += d;
                        if (e > 10) {
                            result += e;
                            if (f > 10) {
                                result += f;
                            }
                        }
                    }
                }
            }
        }
        return result;
    }
}

